# Compute the final grid structure
rows = []
for r in range(30):
    if r <= 5 or r >= 24:
        row = [2] * 30
    else:
        row = [3] * 30
    rows.append(row)

# Display grid structure for verification
def preview(grid, rows_to_show=3):
    # Show first few rows
    for i in range(rows_to_show):
        print(f"Row {i}: {grid[i][:10]}...")
    # Show middle row
    show_row = 15
    print(f"Row {show_row}: {grid[show_row][:10]}...")
    # Show last few rows
    for i in range(30-rows_to_show, 30):
        print(f"Row {i}: {grid[i][:10]}...")

preview(rows)

# Fix the initialization
min_r, max_r, min_c, max_c = 1, 26, 5, 29

rows_out = [[0 for _ in range(30)] for _ in range(30)]

for r in range(30):
    for c in range(30):
        if min_r <= r <= max_r and min_c <= c <= max_c:
            dist_top = r - min_r
            dist_bottom = max_r - r
            dist_left = c - min_c
            dist_right = max_c - c
            min_dist = min(dist_top, dist_bottom, dist_left, dist_right)

            if min_dist >= 3:
                rows_out[r][c] = 3
            elif min_dist <= 2:
                rows_out[r][c] = 2
        else:
            rows_out[r][c] = 0

# Print samples
print("Sample output:")
for (tr, tc) in [(5, 10), (5, 20), (13, 15), (13, 2), (13, 28)]:
    print(f"Row {tr}, Col {tc}: {rows_out[tr][tc]}")

# Print a representative section
print("\nOutput section (rows 10-15, cols 5-15):")
for r in range(10, 16):
    print("  ", " ".join(str(x) for x in rows_out[r][5:15]))

